#[path = "../gallery/mod.rs"] pub mod gallery;
use gallery::{Gallery,Command};
use gallery::workbench::{entries,probe};
use tekes_ui_scene::Scene;
use tekes_ui_render::Renderer;
use tekes_ui_tokens::Theme;
use std::{fs,path::PathBuf};
fn capture(g:&mut Gallery,r:&mut Renderer,out:&std::path::Path,stem:&str,theme:Theme,width:u32,height:u32,scale:u32)->serde_json::Value {g.prepare(r,scale as f32);let mut scene=Scene::new();g.build_scene(&mut scene);let info=probe::inspect(g,&scene,scale as f32);let bytes=r.render_to_rgba8(&scene,g.atlas_mut(),(width*scale,height*scale),scale as f32,Gallery::background(theme)).unwrap();let file=fs::File::create(out.join(format!("{stem}.png"))).unwrap();let mut e=png::Encoder::new(file,width*scale,height*scale);e.set_color(png::ColorType::Rgba);e.set_depth(png::BitDepth::Eight);e.write_header().unwrap().write_image_data(&bytes).unwrap();info}
fn main(){let out=PathBuf::from(std::env::args_os().nth(1).expect("output dir"));fs::create_dir_all(&out).unwrap();let mut r=Renderer::new_headless().unwrap();let mut receipt=vec![];let components=entries().iter().filter(|e|!e.component().is_empty()).collect::<Vec<_>>();assert_eq!(components.len(),45);
for e in components {for theme in Theme::ALL{for (width,height,ts,label) in [(1440,960,0,"default"),(900,720,2,"large-narrow")] {for scale in [1,2]{let mut g=Gallery::new();assert!(g.open_route(e.slug()));g.set_view_size(width as f32,height as f32);g.apply(Command::TextScale(ts));g.set_system_theme(theme);let theme_name=match (theme.is_dark(),theme.is_increased()){(false,false)=>"light",(true,false)=>"dark",(false,true)=>"light-ic",(true,true)=>"dark-ic"};let stem=format!("{}-{label}-{theme_name}-{scale}x",e.slug());let geometry=capture(&mut g,&mut r,&out,&stem,theme,width,height,scale);receipt.push(serde_json::json!({"id":stem,"component":e.component(),"renderer":e.renderer(),"variant":"default","viewport":[width,height],"text_scale_percent":([100,125,150][ts]),"backing_scale":scale,"geometry":geometry}));
if scale==2 && theme==Theme::LIGHT && label=="large-narrow" && ["disclosure","menu","dialog","select","popover","command-palette","combo-box"].contains(&e.renderer()){probe::click(&mut g,if e.renderer()=="combo-box"{1000}else{20});let opened=format!("{stem}-open");let geometry=capture(&mut g,&mut r,&out,&opened,theme,width,height,scale);receipt.push(serde_json::json!({"id":opened,"component":e.component(),"renderer":e.renderer(),"variant":"actual-input-open","viewport":[width,height],"text_scale_percent":150,"backing_scale":scale,"geometry":geometry}));}
}}}fs::write(out.join("manifest.json"),serde_json::to_vec_pretty(&receipt).unwrap()).unwrap();eprintln!("rendered {} ({} captures)",e.component(),receipt.len());}
assert_eq!(receipt.iter().filter(|x|x["variant"]=="default").count(),720);}
